using UnityEngine;
using System.Collections.Generic;
using UnityEngine.EventSystems;
using HighlightPlus;

public class TubeBuilderManager : MonoBehaviour
{
    public static TubeBuilderManager Instance;

    [Header("配置")]
    public portChanel CurrentjointChanel; // 特定Tag
    public GameObject pneumaticPrefab, xixianPrefab, cuxianPrefab;    // 带有 BezierRendererInverse 脚本的气管预制体

    private bool isSelecting = false;
    private Transform firstJoint;
    private Transform secondJoint;

    private void Awake() => Instance = this;


    public void StartBuildPneumaticTube()
    { StartBuildTube("pneumatic"); }

    public void StartBuildtinckwireTube()
    { StartBuildTube("tinckElec"); }
    public void StartBuildwireTube()
    { StartBuildTube("simplleElec"); }

    // --- 1. UI 按钮调用的方法 ---
    public void StartBuildTube(string tubeType)
    {
        EndSelection();
        isSelecting = true;
        firstJoint = null;
        secondJoint = null;
        CurrentjointChanel= (portChanel)System.Enum.Parse(typeof(portChanel), tubeType);
        // 查找并高亮所有接头
        GameObject[] joints = GameObject.FindGameObjectsWithTag(tubeType);

        if (joints.Length < 2)
        {
            Debug.LogWarning("没有找到足够链接 Tag '" + tubeType + "' 的接头对象！");
            return;
        }
        foreach (var joint in joints)
        {
            PortBase port = joint.GetComponent<PortBase>();
            if (port != null && port.isOccupied && !port.isStackable)
            {
            //    Debug.LogWarning("该接头已经连接！");

            }
            else
            {
                // 这里调用你的高亮架构
                SetJointHighlight(joint, true);
            }

        }
   //     Debug.Log("进入放置模式，请选择第一个接头");
    }

    // --- 2. 交互逻辑 ---
    private void Update()
    {
        if (!isSelecting) return;

        if (GetInputDown(out Vector3 screenPos))
        {
            // 1. 排除真正的 UI（仅限 Canvas 上的元素）
            if (IsClickingRealUI(screenPos))
            {
       //         Debug.Log("点到了真正的 UI 按钮，跳过逻辑");
                return;
            }

            // 2. 执行你的接头检测逻辑
            Ray ray = Camera.main.ScreenPointToRay(screenPos);
            if (Physics.Raycast(ray, out RaycastHit hit))
            {
                //Debug.Log("射线击中了 3D 物体: " + hit.transform.name);

                if (hit.transform.CompareTag(CurrentjointChanel.ToString()))
                {
                    HandleJointSelection(hit.transform);
                }
            }
        }
    }

    private void HandleJointSelection(Transform jointTransform)
    {
        PortBase port = jointTransform.GetComponent<PortBase>();
        if (port != null && !port.isStackable&& port.isOccupied )
        {
            //Debug.LogWarning("该接头已经连接了气管！");
            return;
        }

        if (firstJoint == null)
        {
            firstJoint = jointTransform;
          //  Debug.Log("已选择第一个接头: " + firstJoint.name);
        }
        else if (secondJoint == null && (jointTransform != firstJoint))
        {
            secondJoint = jointTransform;
          //  Debug.Log("已选择第二个接头: " + secondJoint.name);
            CreateTube();
        }
    }

    private void CreateTube()
    {
        GameObject newTube = null;

        // 1. 实例化正确的管线预制体
        switch (CurrentjointChanel)
        {
            case portChanel.pneumatic:
                newTube = Instantiate(pneumaticPrefab);
                break;
            case portChanel.tinckElec:
                newTube = Instantiate(xixianPrefab); // 确保已挂载 DynamicWire
                break;
            case portChanel.simplleElec:
                newTube = Instantiate(cuxianPrefab);  // 确保已挂载 DynamicWire
                break;
        }

        if (newTube == null) return;
        newTube.transform.position = Vector3.zero;

        // 2. 获取两端的物理接口组件
        PortBase portA = firstJoint.GetComponent<PortBase>();
        PortBase portB = secondJoint.GetComponent<PortBase>();

        // 3. 【核心兼容适配修改】：分流处理电气导线和气动管线
        if (CurrentjointChanel == portChanel.tinckElec || CurrentjointChanel == portChanel.simplleElec)
        {
            // 抓取全新的多态电线组件
            DynamicWire wireTopology = newTube.GetComponent<DynamicWire>();

            if (wireTopology != null && portA != null && portB != null)
            {
                Debug.Log($"<color=green>[兼容适配成功]</color> 成功抓取到新电线组件，开始初始化拓扑边...");
                // 传入两端 PortBase 上 Awake 时自动动态生成的电路节点 (circuitNode)
                wireTopology.SetupWire(portA.circuitNode, portB.circuitNode);
            }
            else
            {
                Debug.LogError($"<color=red>[组件丢失错误]</color> 电线预制体上未找到全新的 DynamicWire 脚本，或者接口缺失！");
            }
        }
        else
        {
            // 如果是纯气动管线（pneumatic），依然保留你原本的老版 bezier 赋值逻辑
            var oldBezier = newTube.GetComponent<linerendeler>();
            if (oldBezier != null)
            {
                oldBezier.p0 = firstJoint;
                oldBezier.p2 = secondJoint;
            }
        }

        // 4. 保持你原系统的物理状态绑定（让接头知道自己被占用了）
        if (portA != null && portB != null)
        {
            portA.OnConnect(portB);
            portB.OnConnect(portA);
            portA.isOccupied = true;
            portB.isOccupied = true;
        }

        // 5. 结束选择模式，关闭高亮
        EndSelection();
    }

    private void EndSelection()
    {
        //Debug.Log("清除选择信息");
        isSelecting = false;
        GameObject[] joints = GameObject.FindGameObjectsWithTag(CurrentjointChanel.ToString());

        foreach (var joint in joints)
        {
            SetJointHighlight(joint, false);
        }
    }

    // --- 工具方法 ---
    private bool GetInputDown(out Vector3 pos)
    {
        pos = Vector3.zero;
        if (Input.touchCount > 0 && Input.GetTouch(0).phase == TouchPhase.Began)
        {
            pos = Input.GetTouch(0).position;
            return true;
        }
        if (Input.GetMouseButtonDown(0))
        {
            pos = Input.mousePosition;
            return true;
        }
        return false;
    }

    // 高亮架构预留
    private void SetJointHighlight(GameObject obj, bool active)
    {
        obj.GetComponent<HighlightEffect>().highlighted = active;
        // 此处接入你的高亮插件或代码
        // 例如：obj.GetComponent<Outline>().enabled = active;
    }

    private bool IsPointerOverUI()
    {
        // 如果 EventSystem 为空或者根本没激活，直接返回 false
        if (EventSystem.current == null || !EventSystem.current.enabled) return false;

        int pointerId = -1;
        if (Input.touchCount > 0) pointerId = Input.GetTouch(0).fingerId;

        // 如果连 Canvas 都关了，理论上不应该有任何物体被射线击中
        return EventSystem.current.IsPointerOverGameObject(pointerId);
    }

    string GetGameObjectPath(GameObject obj)
    {
        string path = "/" + obj.name;
        while (obj.transform.parent != null)
        {
            obj = obj.transform.parent.gameObject;
            path = "/" + obj.name + path;
        }
        return path;
    }

    // 专门用来过滤“真正的 UI”的方法
    private bool IsClickingRealUI(Vector2 pos)
    {
        PointerEventData eventData = new PointerEventData(EventSystem.current);
        eventData.position = pos;
        List<RaycastResult> results = new List<RaycastResult>();
        EventSystem.current.RaycastAll(eventData, results);

        foreach (var res in results)
        {
            // 只有当物体属于 UI 层（Layer 5），才判定为点击了 UI
            if (res.gameObject.layer == 5)
            {
                return true;
            }
        }
        return false;
    }
}

//物品摆放场景放置物体按钮脚本


using Hypertonic.GridPlacement;
using System.Collections;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using Hypertonic.GridPlacement.Example.BasicDemo;

public class UI_TestPanelItemBTN : MonoBehaviour
{

    public Item itemins;
    [HideInInspector]
    public int itemnum;
    public int chazhi = 0;
    public Image itemImage;
    public TextMeshProUGUI numText, itemName;
    public static event System.Action<GameObject> OnOptionSelected;


    private Button btn;
    public GameObject _gridObjectToSpawnPrefab;
    private GameObject objectToPlace;

    // Start is called before the first frame update
    void Start()
    {

        btn = GetComponent<Button>();
        btn.onClick.AddListener(UseItem);
        btn.interactable=false;
        GridControlManager_sample.OnObjectPlacedOnGrid += HandleObjectPlacedOnGrid;
    }
    void OnDestroy()
    {
        GridControlManager_sample.OnObjectPlacedOnGrid -= HandleObjectPlacedOnGrid;
    }
    public void ClearData()
    {
        /*
        itemins = new Item("",0,null);
        num = 0;
        itemImage.sprite = null;
        numText.text = string.Empty;
        itemName.text = string.Empty;
        _gridObjectToSpawnPrefab = null;

        */
    }

    public void Init(Item itemperfab, int num)
    {
        itemins = itemperfab;
        itemnum = num - chazhi;
        itemImage.sprite = itemperfab.itemImage;
        numText.text = itemnum.ToString();
        itemName.text = itemperfab.itemName;
        _gridObjectToSpawnPrefab = itemperfab.prefab;
    }

    void Update()
    {
        UpdateUIState();
    }
    private void HandleObjectPlacedOnGrid(GameObject @object)
    {
        Debug.Log("@object.name");
        if (@object.GetComponent<Item3D>().itemUI == this)
        {
            if (!@object.GetComponent<Item3D>().hasCreate)
            {
                @object.GetComponent<Item3D>().hasCreate = true;
                // 3. 减少本地记录的数量并更新 UI
                itemnum--;
                chazhi++;
                UpdateUIState();
                // 4. 从全局背包系统移除
                // ItemManager.Instance.RemoveItem(this.item, 1);
               // SimulationLoop.Instance.gridInScene.Add(@object);
            }

        }



    }

    public void UseItem()
    {
        // 1. 检查库存：如果数量已经为 0，理论上按钮由于交互禁用无法点击，但逻辑检查作为双重保险
        if (itemnum <= 0 || !ItemManager.Instance.inventory.ContainsKey(this.itemins))
        {
            Debug.LogWarning("物品数量不足，无法使用！");
            return;
        }

        // 2. 预处理：清理并归还当前可能正在放置的任何物体
        ClearAndReturnCurrentPlacement();
        // 5. 生成并进入放置模式
        objectToPlace = Instantiate(_gridObjectToSpawnPrefab, GridManagerAccessor.GridManager.GetGridPosition(), Quaternion.identity);
        objectToPlace.name = _gridObjectToSpawnPrefab.name;

        if (!objectToPlace.TryGetComponent(out Item3D gridObject))
        {
            objectToPlace.AddComponent<Item3D>();
        }
        objectToPlace.GetComponent<Item3D>().itemUI = this;
        objectToPlace.GetComponent<Item3D>().itemSelf = this.itemins;

        OnOptionSelected?.Invoke(objectToPlace);
        GridManagerAccessor.GridManager.EnterPlacementMode(objectToPlace);
    }



    public void ReturnItem()
    {
        // 调用封装函数处理清理工作
        ClearAndReturnCurrentPlacement();
    }

    /// <summary>
    /// 核心封装：取消当前放置模式，销毁场景物体，并处理库存归还及 UI 更新
    /// </summary>
    private void ClearAndReturnCurrentPlacement()
    {
        var gridManager = GridManagerAccessor.GridManager;

        if (gridManager.IsPlacingGridObject)
        {
            GameObject currentPlacingObject = gridManager.ObjectToPlace;

            // 1. 归还逻辑：本地数量增加，全局背包增加
            // num++;
            // ItemManager.Instance.AddItem(this.item, 1);

            // 2. 更新按钮交互性和文字
            // UpdateUIState();

            // 3. 取消放置并销毁
            gridManager.CancelPlacement(hideGrid: false);
            if (currentPlacingObject != null)
            {
                Destroy(currentPlacingObject);
            }
        }
    }

    /// <summary>
    /// 刷新当前按钮的文字显示和交互状态
    /// </summary>
    public void UpdateUIState()
    {

        // 更新数量文字
        if (numText != null)
        {
            numText.text = itemnum.ToString();
        }
        //Debug.Log(num.ToString());
        // 根据数量控制按钮是否可以点击
        if (btn != null)
        {
            btn.interactable = (itemnum > 0);
        }
    }
    private void HandleButtonClicked()
    {
        if (_gridObjectToSpawnPrefab == null)
        {
            Debug.LogError("Error. No prefab assigned to spawn on this selection option");
        }
        if (GridManagerAccessor.GridManager.IsPlacingGridObject)
        {

            //如果正在放置物体，点击按钮会取消放置模式取消正在放置的物体，放置当前脚本设置的物体
            // 1. 获取当前正在摆放但还未确认的物体
            GameObject currentPlacingObject = GridManagerAccessor.GridManager.ObjectToPlace;

            // 2. 取消当前的放置模式（这会重置 VisualManager 和内部状态）
            // 参数 hideGrid: false 表示切换物体时不需要隐藏再显示网格，保持视觉连贯
            GridManagerAccessor.GridManager.CancelPlacement(hideGrid: false);

            // 3. 销毁场景中那个未完成放置的物体
            if (currentPlacingObject != null)
            {
                Destroy(currentPlacingObject);
            }
        }

        GameObject objectToPlace = Instantiate(_gridObjectToSpawnPrefab, GridManagerAccessor.GridManager.GetGridPosition(), new Quaternion());

        objectToPlace.name = _gridObjectToSpawnPrefab.name;

        if (!objectToPlace.TryGetComponent(out ExampleGridObject gridObject))
        {
            objectToPlace.AddComponent<ExampleGridObject>();
        }

        OnOptionSelected?.Invoke(objectToPlace);

        GridManagerAccessor.GridManager.EnterPlacementMode(objectToPlace);
    }



}

using UnityEngine;

[RequireComponent(typeof(LineRenderer))]
public class linerendeler : MonoBehaviour
{
    [Header("Anchor 点（两端接口）")]
    public Transform p0;
    public Transform p2;

    [Header("控制节点（On-Curve Handles）")]
    public Transform handle20; // 20% 位置
    public Transform handle50; // 50% 位置
    public Transform handle80; // 80% 位置

    [Header("渲染与交互配置")]
    [Range(10, 100)]
    public int resolution = 50;
    [Tooltip("点击线条的判定范围（像素）")]
    public float clickThresholdPixels = 30f;
    [Tooltip("初始创建时的弯曲偏移量（控制默认下垂方向和力度）")]
    public Vector3 defaultCurveOffset = new Vector3(0.5f, 0, 0.5f);

    private LineRenderer lineRenderer;
    private Camera mainCamera;

    // --- 线缆注册：存储两端 portandvalve 数据 + PortBase 引用，用于注销时定位 ---
    private portandvalve _wirePortA;
    private portandvalve _wirePortB;
    private PortBase _wireBaseA;
    private PortBase _wireBaseB;
    private bool isConnectionRegistered = false;

    // 存储样条曲线的所有核心节点
    private Vector3[] controlPoints = new Vector3[5];
    // 1. 在变量声明区域新增一个标记
    private bool isInitialized = false;
    void Start()
    {
        lineRenderer = GetComponent<LineRenderer>();
        lineRenderer.positionCount = resolution;
        mainCamera = Camera.main;
        /*
                // 如果三个控制点都在原点，且首尾已经连接，则进行弯曲初始化
                if (handle20 != null && handle50 != null && handle80 != null && p0 != null && p2 != null)
                {
                    if (handle50.position == Vector3.zero)
                    {
                        InitializeHandlesCurved();
                    }
                }
        */
        // 默认开始时隐藏控制点
        SetHandlesActive(false);
    }

    void Update()
    {
        // 防呆机制：缺少任何一个节点则自毁
        if (p0 == null || p2 == null || handle20 == null || handle50 == null || handle80 == null)
        {
            Debug.LogWarning("存在未绑定的控制点，管线已销毁！");
            Destroy(this.gameObject);
            return;
        }
        // 2.核心修复：延迟到 Update 中进行初始化
        // 确保 p0 和 p2 已经有了真实的物理距离（避免在同一点初始化）且只执行一次
        if (!isInitialized && Vector3.Distance(p0.position, p2.position) > 0.01f)
        {
            InitializeHandlesCurved();

            // ---> [新增] 在初始化曲线的同时，注册连接数据 <---
            RegisterConnection();


            isInitialized = true;
        }

        DrawSpline();
        HandleSelectionLogic();
    }

    private void OnDestroy()
    {
        // ---> [新增] 销毁管线时，从 SimulationLoop 中移除连接数据 <---
        UnregisterConnection();

        // 注意：Unity 的 Destroy 是延迟执行的。
        // 当 DeleteAllValves 先删元器件时，端口 GameObject 被标记为销毁但还没回收，
        // 此时 p0 != null（Unity fake null）但 GetComponent 可能返回 null。
        // 所以需要双重检查：p0 存在 + GetComponent 成功
        PortBase portA = null;
        PortBase portB = null;
        if (p0 != null  )
        { portA = p0.GetComponent<PortBase>(); }

        if (p2 != null)
        { portB = p2.GetComponent<PortBase>(); }


        if (portA != null && portB != null)
        {
            portA.Disconnect();
            portB.Disconnect();

        }
    }

    // --- 1. 核心绘制逻辑 (Catmull-Rom 样条) ---
    void DrawSpline()
    {
        // 1. 更新当前的所有控制节点位置
        controlPoints[0] = p0.position;
        controlPoints[1] = handle20.position;
        controlPoints[2] = handle50.position;
        controlPoints[3] = handle80.position;
        controlPoints[4] = p2.position;

        // 2. 将整条线等分为 resolution 个点进行渲染
        for (int i = 0; i < resolution; i++)
        {
            float t = i / (float)(resolution - 1);
            Vector3 position = GetPointOnSpline(t);
            lineRenderer.SetPosition(i, position);
        }
    }

    // 根据总进度 t (0~1) 获取样条曲线上的点
    Vector3 GetPointOnSpline(float t)
    {
        int numSections = controlPoints.Length - 1; // 一共 4 段
        // 确定当前 t 属于哪一个线段 (0-1, 1-2, 2-3, 3-4)
        int currSection = Mathf.Min(Mathf.FloorToInt(t * numSections), numSections - 1);
        // 计算在该线段内的局部进度 localT
        float localT = (t * numSections) - currSection;

        // 获取 Catmull-Rom 计算所需的 4 个参考点
        Vector3 pA = GetNode(currSection - 1);
        Vector3 pB = GetNode(currSection);     // 线段起点
        Vector3 pC = GetNode(currSection + 1); // 线段终点
        Vector3 pD = GetNode(currSection + 2);

        return GetCatmullRomPosition(localT, pA, pB, pC, pD);
    }

    // 安全获取节点（处理首尾越界，生成虚拟延长点以保持切线平滑）
    Vector3 GetNode(int index)
    {
        if (index < 0)
            return controlPoints[0] + (controlPoints[0] - controlPoints[1]);
        if (index >= controlPoints.Length)
            return controlPoints[controlPoints.Length - 1] + (controlPoints[controlPoints.Length - 1] - controlPoints[controlPoints.Length - 2]);

        return controlPoints[index];
    }

    // 数学工具：标准 Catmull-Rom 插值公式
    Vector3 GetCatmullRomPosition(float t, Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3)
    {
        float t2 = t * t;
        float t3 = t2 * t;

        Vector3 a = 2f * p1;
        Vector3 b = p2 - p0;
        Vector3 c = 2f * p0 - 5f * p1 + 4f * p2 - p3;
        Vector3 d = -p0 + 3f * p1 - 3f * p2 + p3;

        return 0.5f * (a + (b * t) + (c * t2) + (d * t3));
    }

    // --- 2. 选择与隐藏逻辑 ---
    void HandleSelectionLogic()
    {
        bool inputDown = false;
        Vector3 inputScreenPos = Vector3.zero;

        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            if (touch.phase == TouchPhase.Began)
            {
                inputDown = true;
                inputScreenPos = touch.position;
            }
        }
        else if (Input.GetMouseButtonDown(0))
        {
            inputDown = true;
            inputScreenPos = Input.mousePosition;
        }

        if (inputDown)
        {
            // 物理射线检查所有控制球
            Ray ray = mainCamera.ScreenPointToRay(inputScreenPos);
            if (Physics.Raycast(ray, out RaycastHit hit))
            {
                if (hit.transform == handle20 || hit.transform == handle50 || hit.transform == handle80 ||
                    hit.transform == p0 || hit.transform == p2)
                {
                    SetHandlesActive(true);
                    return;
                }
            }

            // 屏幕空间数学检查
            if (IsClickOnLine(inputScreenPos))
            {
                SimulationLoop.Instance.currentLine = this.gameObject;
                SetHandlesActive(true);
            }
            else
            {
                SetHandlesActive(false);
            }
        }
    }

    bool IsClickOnLine(Vector2 clickPos)
    {
        for (int i = 0; i < resolution - 1; i++)
        {
            Vector3 worldPos1 = lineRenderer.GetPosition(i);
            Vector3 worldPos2 = lineRenderer.GetPosition(i + 1);

            Vector2 screenPos1 = mainCamera.WorldToScreenPoint(worldPos1);
            Vector2 screenPos2 = mainCamera.WorldToScreenPoint(worldPos2);

            float distance = DistanceToSegment(clickPos, screenPos1, screenPos2);

            if (distance <= clickThresholdPixels)
            {
                return true;
            }
        }
        return false;
    }

    float DistanceToSegment(Vector2 p, Vector2 v, Vector2 w)
    {
        float sqrLength = (v - w).sqrMagnitude;
        if (sqrLength == 0) return Vector2.Distance(p, v);

        float t = Mathf.Max(0, Mathf.Min(1, Vector2.Dot(p - v, w - v) / sqrLength));
        Vector2 projection = v + t * (w - v);

        return Vector2.Distance(p, projection);
    }

    // --- 3. 状态控制与初始化 ---
    void SetHandlesActive(bool active)
    {


        if (handle20 != null) handle20.gameObject.SetActive(active);
        if (handle50 != null) handle50.gameObject.SetActive(active);
        if (handle80 != null) handle80.gameObject.SetActive(active);
    }

    [ContextMenu("Initialize Handles Curved")]
    public void InitializeHandlesCurved()
    {
        if (p0 != null && p2 != null && handle20 != null && handle50 != null && handle80 != null)
        {
            Vector3 startPos = p0.position;
            Vector3 endPos = p2.position;

            // 基于二次抛物线规律 4*t*(1-t) 计算下垂权重，让管线呈现自然的U型
            handle20.position = Vector3.Lerp(startPos, endPos, 0.2f) + defaultCurveOffset * 0.64f;
            handle50.position = Vector3.Lerp(startPos, endPos, 0.5f) + defaultCurveOffset * 1.00f;
            handle80.position = Vector3.Lerp(startPos, endPos, 0.8f) + defaultCurveOffset * 0.64f;
        }
    }

    // --- 注册连接数据到 SimulationLoop ---
    private void RegisterConnection()
    {
        if (SimulationLoop.Instance == null || p0 == null || p2 == null) return;

        PortBase portA = p0.GetComponent<PortBase>();
        PortBase portB = p2.GetComponent<PortBase>();

        if (portA != null && portB != null)
        {
            // 缓存数据，注销时即使 p0/p2 已销毁也能通过 FindObjectsByType 查到
            _wirePortA = portA.portandvalve;
            _wirePortB = portB.portandvalve;
            _wireBaseA = portA;
            _wireBaseB = portB;

            SimulationLoop.Instance.RegisterWire(portA, portB);
            isConnectionRegistered = true;
        }
        else
        {
            Debug.LogWarning("管线两端的接口缺少 PortBase 组件，无法注册线缆！");
        }
    }

    // --- 从 SimulationLoop 注销连接数据 ---
    private void UnregisterConnection()
    {
        if (isConnectionRegistered && SimulationLoop.Instance != null)
        {
            // 用缓存的 PortBase 引用注销（包含唯一实例信息）
            SimulationLoop.Instance.UnregisterWire(_wireBaseA, _wireBaseB);
            isConnectionRegistered = false;
            _wireBaseA = null;
            _wireBaseB = null;
        }
    }
}

